type Item = { id: string; title: string };
type RowProps = { item: Item; onPress: (id: string) => void };

const Row = React.memo(({ item, onPress }: RowProps) => (
  <Pressable onPress={() => onPress(item.id)}>
    <Text>{item.title}</Text>
  </Pressable>
));

function List({ data }: { data: Item[] }) {
  const [selected, setSelected] = useState<string | null>(null);
  return (
    <FlatList
      data={data}
      extraData={selected}
      renderItem={({ item }) => <Row item={item} onPress={(id) => setSelected(id)} />}
    />
  );
}

type Props = { roomId: string; onSend: (roomId: string, text: string) => void };

function ChatInput({ roomId, onSend }: Props) {
  const [text, setText] = useState('');

  const handleSend = useCallback(() => {
    if (!text.trim()) return;
    onSend(roomId, text);
    setText('');
  }, [roomId, onSend]);

  return (
    <View>
      <TextInput value={text} onChangeText={setText} />
      <SendButton onPress={handleSend} />
    </View>
  );
}

type Todo = { id: string; title: string; done: boolean };
type RowProps = { todo: Todo; onToggle: (id: string) => void };

const TodoRow = memo(({ todo, onToggle }: RowProps) => (
  <Pressable onPress={() => onToggle(todo.id)}>
    <Text>{todo.done ? '[x]' : '[ ]'} {todo.title}</Text>
  </Pressable>
));

function TodoList({ initial }: { initial: Todo[] }) {
  const [todos, setTodos] = useState(initial);
  const toggle = useCallback((id: string) => {
    setTodos((prev) => {
      const todo = prev.find((t) => t.id === id)!;
      todo.done = !todo.done;
      return [...prev];
    });
  }, []);
  return <FlatList data={todos} renderItem={({ item }) => <TodoRow todo={item} onToggle={toggle} />} />;
}
